// Normalize either a HubSpot deal object (from Fetch Open Deals) or a webhook payload into
// one internal schema. HubSpot's native node returns deals as { id, properties: {...} }.
// If your webhook sends a different CRM's shape, add a branch here.

const isHubSpotShape = !!$json.properties;
const d = isHubSpotShape ? $json.properties : ($json.deal || $json);
const hubspotId = isHubSpotShape ? $json.id : null;

const now = new Date();

const lastActivityRaw = isHubSpotShape
  ? (d.notes_last_activity_date || d.hs_lastmodifieddate)
  : d.last_activity_date;
const lastActivity = lastActivityRaw ? new Date(lastActivityRaw) : null;


const stageEntered = isHubSpotShape ? null : (d.stage_entered_date ? new Date(d.stage_entered_date) : null);

const closeDateRaw = isHubSpotShape ? d.closedate : d.close_date;
const closeDate = closeDateRaw ? new Date(closeDateRaw) : null;

const daysSince = (date) => date ? Math.floor((now - date) / (1000 * 60 * 60 * 24)) : -1;

return {
  json: {
    deal_id: isHubSpotShape ? hubspotId : (d.deal_id || d.id),
    deal_name: isHubSpotShape ? d.dealname : (d.deal_name || d.name),

    owner_email: isHubSpotShape ? null : d.owner_email,
    owner_slack_id: isHubSpotShape ? null : (d.owner_slack_id || null),
    hubspot_owner_id: isHubSpotShape ? d.hubspot_owner_id : null,
    deal_value: isHubSpotShape ? Number(d.amount || 0) : (d.amount || d.deal_value || 0),
    stage: isHubSpotShape ? d.dealstage : d.stage,
    days_since_last_activity: daysSince(lastActivity),
    days_in_current_stage: daysSince(stageEntered),
    avg_stage_duration_days: d.avg_stage_duration_days || 14,

    stakeholder_count: d.stakeholder_count || (d.contacts ? d.contacts.length : 1),
    close_date_pushes: d.close_date_pushes || 0,
    has_next_step: !!d.next_step,
    close_date: closeDateRaw || null
  }
};

// Deterministic stall-risk scorer -- same weighted-factor pattern as the Renewal Risk Analyser.
const d = $json;
let score = 0;
const factors = [];

if (d.days_since_last_activity > 30) {
  score += 0.40;
  factors.push('No activity in over 30 days');
} else if (d.days_since_last_activity > 14) {
  score += 0.25;
  factors.push('No activity in over 14 days');
}

if (d.avg_stage_duration_days > 0 && d.days_in_current_stage > d.avg_stage_duration_days * 1.5) {
  score += 0.20;
  factors.push('Stalled in current stage well beyond average duration');
}

if (d.stakeholder_count <= 1) {
  score += 0.15;
  factors.push('Single-threaded: only one stakeholder engaged');
}

if (d.close_date_pushes >= 2) {
  score += 0.20;
  factors.push('Close date pushed back multiple times');
} else if (d.close_date_pushes === 1) {
  score += 0.10;
  factors.push('Close date pushed back once');
}

if (!d.has_next_step) {
  score += 0.15;
  factors.push('No next step defined');
}

score = Math.min(Math.round(score * 100) / 100, 1.0);

let tier = 'low';
if (score >= 0.65) tier = 'high';
else if (score >= 0.35) tier = 'medium';

if (factors.length === 0) {
  factors.push('No significant stall risk factors detected');
}

return {
  json: {
    ...d,
    risk_score: score,
    risk_tier: tier,
    contributing_factors: factors
  }
};

