// Error path from the generator LLM call: assign a safe default and notify ops.
const source = $('Calculate Stall Risk Score').item.json;
return {
  json: {
    ...source,
    failure_stage: 'llm_generate',
    error_message: $json.error ? ($json.error.message || JSON.stringify($json.error)) : 'Unknown error from generator LLM call',
    log_status: 'llm_generate_failed'
  }
};

// The Basic LLM Chain node + Structured Output Parser already deliver validated JSON --
// no manual JSON.parse needed. The parsed object lands at $json.output in most current
// n8n/LangChain versions; fall back to $json directly for older versions that flatten it.
const parsed = $json.output || $json;

const required = ['likely_cause', 'recommended_action', 'urgency', 'confidence'];
for (const field of required) {
  if (!(field in parsed)) throw new Error('LLM generator output missing field: ' + field + ' -- check the output-parser field path for your n8n version');
}


const usage = $json.tokenUsage || $json.usage || {};
const RATE_IN_PER_1K = 0.003;
const RATE_OUT_PER_1K = 0.015;
const generatorCost = ((usage.promptTokens || usage.prompt_tokens || 0) / 1000) * RATE_IN_PER_1K
  + ((usage.completionTokens || usage.completion_tokens || 0) / 1000) * RATE_OUT_PER_1K;

return {
  json: {
    ...$('Calculate Stall Risk Score').item.json,
    diagnosis: parsed,
    llm_generator_tokens: usage,
    llm_generator_cost_usd: Math.round(generatorCost * 100000) / 100000
  }
};

parameters.text:
=You are auditing a sales stall diagnosis for accuracy against the raw deal data.

Deal data and proposed diagnosis:
{{ JSON.stringify($json) }}

parameters.jsCode:
// Error path from the auditor LLM call: assign a safe default and notify ops.
const source = $('Parse and Validate LLM Output').item.json;
return {
  json: {
    ...source,
    failure_stage: 'llm_audit',
    error_message: $json.error ? ($json.error.message || JSON.stringify($json.error)) : 'Unknown error from auditor LLM call',
    log_status: 'llm_audit_failed'
  }
};

// Same native-output shape as the generator step -- structured parser output at $json.output,
// falling back to $json directly for older node versions.
const verdict = $json.output || $json;

const required = ['agrees', 'notes'];
for (const field of required) {
  if (!(field in verdict)) throw new Error('LLM auditor output missing field: ' + field + ' -- check the output-parser field path for your n8n version');
}

const source = $('Parse and Validate LLM Output').item.json;


const usage = $json.tokenUsage || $json.usage || {};
const RATE_IN_PER_1K = 0.003;
const RATE_OUT_PER_1K = 0.015;
const auditorCost = ((usage.promptTokens || usage.prompt_tokens || 0) / 1000) * RATE_IN_PER_1K
  + ((usage.completionTokens || usage.completion_tokens || 0) / 1000) * RATE_OUT_PER_1K;
const totalCost = (source.llm_generator_cost_usd || 0) + auditorCost;

return {
  json: {
    ...source,
    auditor_verdict: verdict,
    llm_auditor_tokens: usage,
    llm_auditor_cost_usd: Math.round(auditorCost * 100000) / 100000,
    llm_total_cost_usd: Math.round(totalCost * 100000) / 100000
  }
};

// Guardrails: schema check plus no leaking sensitive deal terms into the wrong channel.
const d = $json;
const violations = [];

const allowedUrgency = ['low', 'medium', 'high'];
if (!allowedUrgency.includes(d.diagnosis.urgency)) {
  violations.push('urgency field out of allowed range');
}
if (typeof d.diagnosis.confidence !== 'number' || d.diagnosis.confidence < 0 || d.diagnosis.confidence > 1) {
  violations.push('confidence field out of 0-1 range');
}
if (!d.diagnosis.recommended_action || d.diagnosis.recommended_action.length < 3) {
  violations.push('recommended_action missing or too short');
}

return {
  json: {
    ...d,
    guardrails_passed: violations.length === 0,
    guardrails_violations: violations
  }
};

// Real duplicate-suppression lookup using n8n workflow static data.

const staticData = $getWorkflowStaticData('global');
staticData.alertHistory = staticData.alertHistory || {};
const record = staticData.alertHistory[$json.deal_id] || null;

return {
  json: {
    ...$json,
    last_alerted_score: record ? record.score : null,
    last_alerted_at: record ? record.at : null
  }
};

// Duplicate suppression: re-alert only if the score moved meaningfully OR it's been 7+ days.
const d = $json;
const scoreMoved = d.last_alerted_score === null || Math.abs(d.risk_score - d.last_alerted_score) >= 0.10;

let daysSinceLastAlert = null;
if (d.last_alerted_at) {
  daysSinceLastAlert = Math.floor((Date.now() - new Date(d.last_alerted_at)) / (1000 * 60 * 60 * 24));
}
const staleAlert = daysSinceLastAlert === null || daysSinceLastAlert >= 7;

return {
  json: {
    ...d,
    should_alert: scoreMoved || staleAlert
  }
};

