// Persist this alert so the next run's Get Last Alert Record can suppress duplicates.
const staticData = $getWorkflowStaticData('global');
staticData.alertHistory = staticData.alertHistory || {};
staticData.alertHistory[$json.deal_id] = { score: $json.risk_score, at: new Date().toISOString() };

return { json: { ...$json, log_status: 'completed_alert_sent' } };

// Combines the business-rule schema check (Guardrails Check) with the native Content Safety
// Guardrails node's verdict. Defensive parsing since the native node's output field names are
// version-sensitive -- adjust the 'flagged'/'violations' extraction below if your version differs.
const d = $json;

let contentSafetyPassed = true;
let contentSafetyViolations = [];
let contentSafetySkipped = false;

if (d.error) {
  // Content Safety Guardrails node errored -- fail open, log it, don't block alerting on an
  // optional check being unavailable.
  contentSafetySkipped = true;
} else {
  // Common shapes across guardrail-style nodes: a boolean flag plus a list of triggered checks.
  const flagged = d.flagged ?? d.blocked ?? (Array.isArray(d.violations) && d.violations.length > 0) ?? false;
  contentSafetyPassed = !flagged;
  contentSafetyViolations = d.violations || d.flaggedChecks || (flagged ? ['content safety check flagged, see native node output for detail'] : []);
}

const violations = [...(d.guardrails_violations || [])];
if (!contentSafetyPassed) violations.push(...contentSafetyViolations);

return {
  json: {
    ...d,
    guardrails_passed: (d.guardrails_passed !== false) && contentSafetyPassed,
    guardrails_violations: violations,
    content_safety_skipped: contentSafetySkipped
  }
};
